#!/usr/bin/env python3
import sys
import json

def read_input():
    try:
        data = json.load(sys.stdin)
    except Exception:
        sys.stderr.write("invalid JSON\n")
        sys.exit(2)
    if not isinstance(data, dict):
        sys.stderr.write("input must be JSON object\n")
        sys.exit(2)
    for key in ("entry", "exit", "lost_ticket"):
        if key not in data:
            sys.stderr.write(f"missing {key}\n")
            sys.exit(2)
    entry = data["entry"]
    exit = data["exit"]
    lost_ticket = data["lost_ticket"]
    if type(entry) is not int or type(exit) is not int or type(lost_ticket) is not bool:
        sys.stderr.write("invalid field types\n")
        sys.exit(2)
    if not (0 <= entry <= 10079) or not (0 <= exit <= 10079):
        sys.stderr.write("entry/exit out of bounds\n")
        sys.exit(2)
    return entry, exit, lost_ticket

def stay_minutes(entry, exit):
    if exit >= entry:
        return exit - entry
    return 10080 - entry + exit

def compute_time_cents(minutes):
    if minutes <= 15:
        return 0
    full_periods = minutes // 1440
    time_cents = full_periods * 1600
    remaining = minutes % 1440
    if remaining:
        started_hours = (remaining + 59) // 60
        period_cents = started_hours * 250
        if period_cents > 1600:
            period_cents = 1600
        time_cents += period_cents
    return time_cents

def count_overnight_nights(entry, minutes):
    start = entry
    end = entry + minutes
    k_start = (start - 120 + 1439) // 1440
    k_end = (end - 1 - 120) // 1440
    if k_end < k_start:
        return 0
    return k_end - k_start + 1

def main():
    entry, exit, lost_ticket = read_input()
    minutes = stay_minutes(entry, exit)
    if minutes <= 15:
        time_cents = 0
        overnight_cents = 0
    else:
        time_cents = compute_time_cents(minutes)
        overnight_cents = 600 * count_overnight_nights(entry, minutes)
    lost_ticket_cents = 2500 if lost_ticket else 0
    total_cents = time_cents + overnight_cents + lost_ticket_cents
    result = {
        "minutes": minutes,
        "time_cents": time_cents,
        "overnight_cents": overnight_cents,
        "lost_ticket_cents": lost_ticket_cents,
        "total_cents": total_cents,
    }
    json.dump(result, sys.stdout, separators=(",", ":"))
    sys.stdout.write("\n")

if __name__ == "__main__":
    main()

